SELECT d.transaction_id,a.name,a.transaction_type,d.database_transaction_begin_time,d.database_transaction_log_record_count,st.session_id,s.is_user_process,s.program_name FROM sys.dm_tran_database_transactions d LEFT JOIN sys.dm_tran_active_transactions a ON a.transaction_id=d.transaction_id LEFT JOIN sys.dm_tran_session_transactions st ON st.transaction_id=d.transaction_id LEFT JOIN sys.dm_exec_sessions s ON s.session_id=st.session_id WHERE d.database_id=DB_ID() AND d.database_transaction_log_record_count>0